css:
:root { --bg-primary: #0f172a; --bg-card: #1e293b; --bg-hover: #334155; --text-primary: #f8fafc; --text-secondary: #94a3b8; --accent: #3b82f6; --accent-hover: #60a5fa; --success: #22c55e; --warning: #f59e0b; --danger: #ef4444; --radius: 8px; --shadow: 0 4px 6px -1px rgba(0,0,0,0.3); }
* { box-sizing: border-box; margin: 0; padding: 0; }
body { font-family: Inter, -apple-system, sans-serif; background: var(--bg-primary); color: var(--text-primary); line-height: 1.6; min-height: 100vh; }

/* layout */
.app { display: grid; grid-template-columns: 240px 1fr; grid-template-rows: 56px 1fr; min-height: 100vh; }
.sidebar { grid-row: 1 / -1; background: var(--bg-card); border-right: 1px solid rgba(255,255,255,0.1); padding: 16px; display: flex; flex-direction: column; gap: 4px; overflow-y: auto; }
.topbar { grid-column: 2; background: var(--bg-card); border-bottom: 1px solid rgba(255,255,255,0.1); display: flex; align-items: center; padding: 0 24px; gap: 16px; }
.main-content { grid-column: 2; padding: 24px; overflow-y: auto; }

/* sidebar */
.logo { font-size: 18px; font-weight: 700; padding: 8px 12px; margin-bottom: 16px; letter-spacing: -0.5px; }
.nav-item { display: flex; align-items: center; gap: 10px; padding: 8px 12px; border-radius: var(--radius); color: var(--text-secondary); text-decoration: none; font-size: 14px; transition: background 0.15s, color 0.15s; cursor: pointer; }
.nav-item:hover { background: var(--bg-hover); color: var(--text-primary); }
.nav-item.active { background: var(--accent); color: white; }
.nav-icon { width: 18px; height: 18px; opacity: 0.7; flex-shrink: 0; }
.nav-item.active .nav-icon { opacity: 1; }
.nav-divider { height: 1px; background: rgba(255,255,255,0.1); margin: 12px 0; }
.nav-section { font-size: 11px; text-transform: uppercase; letter-spacing: 1px; color: var(--text-secondary); padding: 8px 12px; opacity: 0.6; }

/* topbar */
.search-box { flex: 1; max-width: 400px; position: relative; }
.search-box input { width: 100%; padding: 8px 12px 8px 36px; background: var(--bg-primary); border: 1px solid rgba(255,255,255,0.1); border-radius: var(--radius); color: var(--text-primary); font-size: 14px; outline: none; transition: border-color 0.15s; }
.search-box input:focus { border-color: var(--accent); }
.search-box input::placeholder { color: var(--text-secondary); }
.topbar-actions { display: flex; align-items: center; gap: 8px; margin-left: auto; }
.icon-btn { width: 36px; height: 36px; border-radius: 50%; border: none; background: transparent; color: var(--text-secondary); cursor: pointer; display: flex; align-items: center; justify-content: center; transition: background 0.15s, color 0.15s; }
.icon-btn:hover { background: var(--bg-hover); color: var(--text-primary); }
.avatar { width: 32px; height: 32px; border-radius: 50%; background: var(--accent); object-fit: cover; }

/* stats cards */
.stats-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 16px; margin-bottom: 24px; }
.stat-card { background: var(--bg-card); border-radius: var(--radius); padding: 20px; box-shadow: var(--shadow); position: relative; overflow: hidden; }
.stat-card::before { content: ""; position: absolute; top: 0; left: 0; right: 0; height: 3px; background: var(--accent); }
.stat-card.success::before { background: var(--success); }
.stat-card.warning::before { background: var(--warning); }
.stat-card.danger::before { background: var(--danger); }
.stat-label { font-size: 13px; color: var(--text-secondary); text-transform: uppercase; letter-spacing: 0.5px; margin-bottom: 8px; }
.stat-value { font-size: 28px; font-weight: 700; letter-spacing: -1px; }
.stat-change { font-size: 13px; margin-top: 8px; display: flex; align-items: center; gap: 4px; }
.stat-change.up { color: var(--success); }
.stat-change.down { color: var(--danger); }

/* charts area */
.charts-row { display: grid; grid-template-columns: 2fr 1fr; gap: 16px; margin-bottom: 24px; }
.chart-card { background: var(--bg-card); border-radius: var(--radius); padding: 20px; box-shadow: var(--shadow); }
.chart-header { display: flex; justify-content: space-between; align-items: center; margin-bottom: 16px; }
.chart-title { font-size: 16px; font-weight: 600; }
.chart-placeholder { height: 200px; background: repeating-linear-gradient(90deg, var(--bg-hover) 0px, var(--bg-hover) 2px, transparent 2px, transparent 24px); border-radius: 4px; display: flex; align-items: flex-end; justify-content: space-around; padding: 0 8px; }
.bar { width: 16px; background: var(--accent); border-radius: 2px 2px 0 0; transition: height 0.3s; }
.bar:hover { background: var(--accent-hover); }
.donut-placeholder { width: 160px; height: 160px; border-radius: 50%; border: 20px solid var(--accent); border-top-color: var(--success); border-right-color: var(--warning); margin: 20px auto; transform: rotate(-45deg); }

/* table */
.table-card { background: var(--bg-card); border-radius: var(--radius); box-shadow: var(--shadow); overflow: hidden; }
.table-header { padding: 16px 20px; border-bottom: 1px solid rgba(255,255,255,0.1); display: flex; justify-content: space-between; align-items: center; }
.table-title { font-size: 16px; font-weight: 600; }
table { width: 100%; border-collapse: collapse; }
th { text-align: left; padding: 12px 20px; font-size: 12px; text-transform: uppercase; letter-spacing: 0.5px; color: var(--text-secondary); border-bottom: 1px solid rgba(255,255,255,0.1); }
td { padding: 12px 20px; font-size: 14px; border-bottom: 1px solid rgba(255,255,255,0.05); }
tr:hover td { background: var(--bg-hover); }
tr:last-child td { border-bottom: none; }
.status-badge { display: inline-flex; align-items: center; gap: 4px; padding: 2px 8px; border-radius: 12px; font-size: 12px; font-weight: 500; }
.status-badge.active { background: rgba(34,197,94,0.15); color: var(--success); }
.status-badge.pending { background: rgba(245,158,11,0.15); color: var(--warning); }
.status-badge.error { background: rgba(239,68,68,0.15); color: var(--danger); }

/* buttons */
.btn { display: inline-flex; align-items: center; gap: 6px; padding: 8px 16px; border-radius: var(--radius); font-size: 14px; font-weight: 500; border: none; cursor: pointer; transition: background 0.15s, transform 0.1s, box-shadow 0.15s; }
.btn:active { transform: scale(0.98); }
.btn-primary { background: var(--accent); color: white; }
.btn-primary:hover { background: var(--accent-hover); box-shadow: 0 0 0 3px rgba(59,130,246,0.3); }
.btn-outline { background: transparent; color: var(--text-secondary); border: 1px solid rgba(255,255,255,0.2); }
.btn-outline:hover { background: var(--bg-hover); color: var(--text-primary); }

/* tooltip */
.tooltip { position: relative; }
.tooltip::after { content: attr(data-tip); position: absolute; bottom: calc(100% + 8px); left: 50%; transform: translateX(-50%); padding: 4px 8px; background: var(--text-primary); color: var(--bg-primary); border-radius: 4px; font-size: 12px; white-space: nowrap; opacity: 0; pointer-events: none; transition: opacity 0.15s; z-index: 10; }
.tooltip:hover::after { opacity: 1; }

/* responsive */
@media (max-width: 1024px) {
  .stats-grid { grid-template-columns: repeat(2, 1fr); }
  .charts-row { grid-template-columns: 1fr; }
}
@media (max-width: 768px) {
  .app { grid-template-columns: 1fr; }
  .sidebar { display: none; }
  .topbar { grid-column: 1; }
  .main-content { grid-column: 1; padding: 16px; }
  .stats-grid { grid-template-columns: 1fr; }
  .table-card { overflow-x: auto; }
  th:nth-child(n+3), td:nth-child(n+3) { display: none; }
}

/* scrollbar */
::-webkit-scrollbar { width: 6px; }
::-webkit-scrollbar-track { background: transparent; }
::-webkit-scrollbar-thumb { background: var(--bg-hover); border-radius: 3px; }

/* animations */
@keyframes fadeIn { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: none; } }
.stat-card { animation: fadeIn 0.3s ease-out; }
.stat-card:nth-child(2) { animation-delay: 0.05s; }
.stat-card:nth-child(3) { animation-delay: 0.1s; }
.stat-card:nth-child(4) { animation-delay: 0.15s; }

/* filter effects */
.avatar-glow { filter: drop-shadow(0 0 6px var(--accent)); }
.backdrop-blur { backdrop-filter: blur(8px); background: rgba(15,23,42,0.8); }
